//
// This is only a SKELETON file for the 'Twelve Days' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const DAYS = [
  'first',
  'second',
  'third',
  'fourth',
  'fifth',
  'sixth',
  'seventh',
  'eighth',
  'ninth',
  'tenth',
  'eleventh',
  'twelfth',
];

const GIFTS = [
  'a Partridge in a Pear Tree',
  'two Turtle Doves',
  'three French Hens',
  'four Calling Birds',
  'five Gold Rings',
  'six Geese-a-Laying',
  'seven Swans-a-Swimming',
  'eight Maids-a-Milking',
  'nine Ladies Dancing',
  'ten Lords-a-Leaping',
  'eleven Pipers Piping',
  'twelve Drummers Drumming',
];

const verse = (day) => {
  const gifts = GIFTS.slice(0, day)
    .reverse()
    .map((gift, index) => (index === day - 2 ? gift : `and ${gift}`))
    .join(', ');
  return `On the ${DAYS[day - 1]} day of Christmas my true love gave to me: ${gifts}.\n`;
};

export const recite = (startVerse, endVerse = startVerse) =>
  Array.from({ length: endVerse - startVerse + 1 }, (_, i) => verse(startVerse + i)).join('\n');

